    low_limit : INT := 10;
    high_limit : INT := 90;
END_VAR

IF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

