PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL;
    StartDebounced : BOOL;
    StopDebounced : BOOL;
    GuardTimer : TON;
END_VAR

-- Debounce StartPB
StartDebounced := StartPB AND NOT StopPB;

-- Debounce StopPB
StopDebounced := StopPB AND NOT StartPB;

-- Safety guard timer
GuardTimer(IN := GuardClosed, PT := T#2s);

-- Main logic
IF Fault OR NOT GuardTimer.Q THEN
    Running := FALSE;
ELSIF StartDebounced AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
ELSIF StopDebounced OR NOT GuardTimer.Q THEN
    Running := FALSE;
END_IF;

Conveyor := Running;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL;
    StartTimer : TON;
END_VAR

// Start the conveyor if conditions are met and StartPB is pressed
IF StartPB AND GuardClosed AND NOT Fault THEN
    StartTimer(IN := TRUE, PT := T#0s);
ELSIF StopPB OR NOT GuardClosed OR Fault THEN
    StartTimer(IN := FALSE);
END_IF;

// Latch the conveyor state
Running := StartTimer.Q;

// Set the output based on the current state and safety conditions
Conveyor := Running AND GuardClosed AND NOT Fault;
END_PROGRAM

