PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: -- Fill
        IF Level >= LVL_HIGH THEN
            State := 2;
        ELSE
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
    2: -- Heat
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        ELSE
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        END_IF;
    3: -- React
        T1(IN := TRUE, PT := PT_REACT);
        IF T1.Q THEN
            State := 4;
        ELSE
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        END_IF;
    4: -- Drain
        IF Level <= LVL_LOW THEN
            State := 0;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        END_IF;
END_CASE;

-- Safety conditions
FillValve AND DrainValve := FALSE;
Heater OR Agitator AND Level < LIQ_MIN := FALSE;

END_PROGRAM

