        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        FillTimer(IN := TRUE, PT := PT_REACT);
        IF FillTimer.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
