PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

IF NOT EStop THEN
    State := IDLE;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND (State = IDLE OR State = DRAIN) THEN
    CASE State OF
        IDLE :
            IF Level >= LIQ_MIN THEN
                State := FILL;
            END_IF;
        FILL :
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            ELSE
                FillValve := TRUE;
            END_IF;
        HEAT :
            IF Temp >= TEMP_SET THEN
                State := REACT;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;
        REACT :
            IF Ticks(PT_REACT) THEN
                State := DRAIN;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;
        DRAIN :
            IF Level <= LVL_LOW THEN
                State := IDLE;
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Prevent fill and drain valves from being open simultaneously
FillValve := FillValve AND NOT DrainValve;
DrainValve := DrainValve AND NOT FillValve;

END_PROGRAM

PROGRAM batch_reactor
