IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET THEN
    State := 3;
ELSIF State = 3 AND HeatTimer.Q THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        HeatTimer(IN := TRUE, PT := T#1s);
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        HeatTimer(IN := TRUE, PT := T#1s);
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

IF Level < LIQ_MIN OR DrainValve THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
