PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR
IF EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND EStop AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        FillValve := Level < LVL_HIGH AND EStop AND Level >= LIQ_MIN;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        END_IF;
    2: // Heat
        Heater := Temp < TEMP_SET AND EStop AND Level >= LIQ_MIN;
        Agitator := TRUE AND EStop AND Level >= LIQ_MIN;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
        END_IF;
    3: // React
        Heater := TRUE AND EStop AND Level >= LIQ_MIN;
        Agitator := TRUE AND EStop AND Level >= LIQ_MIN;
        IF Temp < TEMP_SET OR NOT EStop OR PT_REACT.T#0s THEN
            State := 4;
        END_IF;
    4: // Drain
        DrainValve := Level > LVL_LOW AND EStop;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

PROGRAM garage
