                State := 1;
                T_C3(IN := FALSE);
                C1 := FALSE;
                C2 := FALSE;
            END_IF;
    END_CASE;
ELSE
    State := 0;
    T_C3(IN := FALSE);
    T_C2(IN := FALSE);
    C1 := FALSE;
    C2 := FALSE;
